"""One failing row and one passing row per data-quality rule (skill: Unit-test focus)."""
import unittest

from shipments_import.rules import validate_batch


def reasons_by_line(rows):
    good, rejected = validate_batch(rows)
    return good, {r.line_no: r.reasons for r in rejected}


class ShipmentIdPresent(unittest.TestCase):
    def test_empty_is_rejected(self):
        _, rej = reasons_by_line([{"shipment_id": "", "weight_kg": "1"}])
        self.assertIn("shipment_id_missing", rej[2])

    def test_whitespace_only_is_rejected(self):
        _, rej = reasons_by_line([{"shipment_id": "   ", "weight_kg": "1"}])
        self.assertIn("shipment_id_missing", rej[2])

    def test_null_is_rejected(self):
        _, rej = reasons_by_line([{"shipment_id": None, "weight_kg": "1"}])
        self.assertIn("shipment_id_missing", rej[2])

    def test_present_passes(self):
        good, rej = reasons_by_line([{"shipment_id": "A1", "weight_kg": "1"}])
        self.assertEqual(rej, {})
        self.assertEqual(good[0].shipment_id, "A1")


class ShipmentIdUniqueInBatch(unittest.TestCase):
    def test_every_copy_of_a_duplicate_is_rejected_not_one_kept(self):
        rows = [{"shipment_id": "A1", "weight_kg": "1"},
                {"shipment_id": "A1", "weight_kg": "2"},
                {"shipment_id": "B2", "weight_kg": "3"}]
        good, rej = reasons_by_line(rows)
        self.assertEqual([g.shipment_id for g in good], ["B2"])
        self.assertIn("shipment_id_duplicate_in_batch", rej[2])
        self.assertIn("shipment_id_duplicate_in_batch", rej[3])

    def test_duplicate_detection_ignores_surrounding_whitespace(self):
        rows = [{"shipment_id": "A1", "weight_kg": "1"},
                {"shipment_id": " A1 ", "weight_kg": "1"}]
        good, rej = reasons_by_line(rows)
        self.assertEqual(good, [])
        self.assertEqual(len(rej), 2)


class WeightInRange(unittest.TestCase):
    def test_negative_is_rejected(self):
        _, rej = reasons_by_line([{"shipment_id": "A1", "weight_kg": "-2.0"}])
        self.assertIn("weight_kg_out_of_range", rej[2])

    def test_zero_is_rejected(self):
        _, rej = reasons_by_line([{"shipment_id": "A1", "weight_kg": "0"}])
        self.assertIn("weight_kg_out_of_range", rej[2])

    def test_above_max_is_rejected(self):
        _, rej = reasons_by_line([{"shipment_id": "A1", "weight_kg": "1000000"}])
        self.assertIn("weight_kg_out_of_range", rej[2])

    def test_max_boundary_passes(self):
        from shipments_import.rules import WEIGHT_KG_MAX
        good, rej = reasons_by_line([{"shipment_id": "A1", "weight_kg": str(WEIGHT_KG_MAX)}])
        self.assertEqual(rej, {})

    def test_not_a_number_is_rejected(self):
        for bad in ("abc", "nan", "inf", "1,5"):
            _, rej = reasons_by_line([{"shipment_id": "A1", "weight_kg": bad}])
            self.assertIn("weight_kg_not_a_number", rej[2], bad)

    def test_missing_is_rejected(self):
        _, rej = reasons_by_line([{"shipment_id": "A1", "weight_kg": ""}])
        self.assertIn("weight_kg_missing", rej[2])

    def test_small_positive_passes(self):
        good, rej = reasons_by_line([{"shipment_id": "A1", "weight_kg": "0.4"}])
        self.assertEqual(rej, {})
        self.assertAlmostEqual(good[0].weight_kg, 0.4)


class AllReasonsKept(unittest.TestCase):
    def test_row_breaking_two_rules_carries_both_reasons(self):
        _, rej = reasons_by_line([{"shipment_id": "", "weight_kg": "-1"}])
        self.assertEqual(set(rej[2]), {"shipment_id_missing", "weight_kg_out_of_range"})

    def test_nothing_is_silently_fixed(self):
        # A rejected row keeps its raw values exactly as received.
        _, rejected = validate_batch([{"shipment_id": " ", "weight_kg": "-2.0"}])
        self.assertEqual(rejected[0].raw, {"shipment_id": " ", "weight_kg": "-2.0"})


if __name__ == "__main__":
    unittest.main()
